makeMtLab(document.getElementById("lab-l27"),{id:"l27",scenarios:[{"label": "Ví dụ: Kết nối lần đầu", "note": "psql hỏi mật khẩu.", "steps": [{"t": "psql -U postgres", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">Password for user postgres:<\/span><\/div>"}, {"t": "Đăng nhập được", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">postgres=#<\/span><\/div>", "ask": {"q": "Dấu # ở cuối dấu nhắc nghĩa là gì?", "o": ["Đang là tài khoản quản trị", "Đang lỗi"], "a": 0}}]}, {"label": "Ví dụ: Tạo CSDL dự án", "note": "Người dùng riêng, CSDL riêng.", "steps": [{"t": "CREATE ROLE mes_app", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">CREATE ROLE<\/span><\/div>"}, {"t": "CREATE DATABASE mes_dev", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">CREATE DATABASE<\/span><\/div>"}, {"t": "Kết nối bằng mes_app", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">mes_dev=&gt;<\/span><\/div>", "say": "<p>Dấu > cho biết không phải quản trị.<\/p>"}]}, {"label": "Lỗi: Quên dấu chấm phẩy", "note": "psql chờ dòng tiếp.", "steps": [{"t": "select version()", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">postgres-#<\/span><\/div>"}, {"t": "Gõ ;", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\"> PostgreSQL 16.15 ...<\/span><\/div>"}]}, {"label": "Lỗi: Sai mật khẩu", "note": "Đọc kỹ thông báo.", "steps": [{"t": "psql -U postgres", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">psql: error: ... password authentication failed for user \"postgres\"<\/span><\/div>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Dùng đúng mật khẩu đặt khi cài; không đặt lại bằng cách sửa file cấu hình nếu không cần<\/p>"}]}, {"label": "Bẫy: Ứng dụng dùng tài khoản postgres", "note": "Quyền quá rộng.", "steps": [{"t": "Collector kết nối bằng postgres", "html": "<p class=\"mt-calc\">Một lỗi SQL có thể xóa cả CSDL khác<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Tài khoản mes_app chỉ sở hữu mes_dev<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l27"),"l27",[{"kind": "num", "t": "PostgreSQL", "d": "<p>Trả lời bằng một số.<\/p>", "items": [{"q": "Cổng mặc định của PostgreSQL?", "a": 5432}, {"q": "Phiên bản chính dùng trong khóa?", "a": 16}, {"q": "Dự án tạo bao nhiêu tài khoản riêng cho ứng dụng?", "a": 1}], "hints": ["Xem phần cài đặt.", "Tài khoản mes_app."], "why": "5432; 16; 1."}, {"kind": "pick", "t": "Lệnh của ai?", "d": "<p>Lệnh psql hay câu SQL?<\/p>", "cats": ["Lệnh psql", "Câu SQL"], "items": [{"q": "\\dt", "a": 0}, {"q": "select version();", "a": 1}, {"q": "\\q", "a": 0}, {"q": "CREATE DATABASE mes_dev;", "a": 1}, {"q": "\\l", "a": 0}], "hints": ["Lệnh psql bắt đầu bằng \\.", "Câu SQL kết thúc bằng ;."], "why": "\\dt, \\q, \\l là lệnh psql; còn lại là SQL."}, {"kind": "order", "t": "Chuẩn bị CSDL", "d": "<p>Sắp xếp.<\/p>", "items": ["Cài PostgreSQL, ghi mật khẩu postgres", "Đăng nhập psql bằng postgres", "CREATE ROLE mes_app", "CREATE DATABASE mes_dev OWNER mes_app", "Chạy 01_schema.sql bằng mes_app"], "hints": ["Cần quyền quản trị để tạo tài khoản.", "Chạy lược đồ bằng tài khoản ứng dụng."], "why": "Cài → đăng nhập → tạo role → tạo CSDL → chạy lược đồ."}]);
mesSim(document.getElementById("sim-l27"),Object.assign({id:"l27"},{kind:"term",title:"psql: tạo người dùng và CSDL của dự án",sub:"Kết quả in theo nội dung bài (phiên bản là ví dụ).",cwd:"C:\\amts\\mini-mes",
 vars:{in:null,role:false,db:false,schema:false},
 prompt:S=>S.in?S.in+"=# ":"PS "+S.cwd+"> ",
 hints:["psql -U postgres","select version();","\\l","CREATE ROLE mes_app LOGIN PASSWORD 'doi-mat-khau';","CREATE DATABASE mes_dev OWNER mes_app;","\\q","psql -U mes_app -d mes_dev -f sql\\01_schema.sql"],
 cmds:[{re:/^psql -U postgres$/i,out:"Password for user postgres: ********\npsql (16.15)\nType \"help\" for help.",fx:(m,S)=>{S.in="postgres"}},
  {re:/^psql -U mes_app -d mes_dev -f sql\\01_schema\.sql$/i,out:(m,S)=>!S.role?{err:"psql: error: FATAL:  password authentication failed for user \"mes_app\""}:!S.db?{err:"psql: error: FATAL:  database \"mes_dev\" does not exist"}:"CREATE SCHEMA\nSET\nCREATE TABLE\nCREATE TABLE\nCREATE TABLE",fx:(m,S)=>{if(S.role&&S.db)S.schema=true}},
  {re:/^select version\(\);$/i,out:(m,S)=>S.in?"                     version\n---------------------------------------------------\n PostgreSQL 16.15, compiled by Visual C++ build 1940, 64-bit\n(1 row)":{err:"select : The term 'select' is not recognized (bạn đang ở PowerShell, chưa vào psql)"}},
  {re:/^select version\(\)$/i,out:(m,S)=>S.in?"(psql chờ dấu ; — câu SQL phải kết thúc bằng dấu chấm phẩy)":{err:"not recognized"}},
  {re:/^\\l$/,out:(m,S)=>" Name     | Owner\n----------+----------\n"+(S.db?" mes_dev  | mes_app\n":"")+" postgres | postgres\n template0| postgres\n template1| postgres"},
  {re:/^CREATE ROLE mes_app LOGIN PASSWORD '[^']+';$/i,out:(m,S)=>S.in==="postgres"?"CREATE ROLE":{err:"ERROR:  permission denied to create role"},fx:(m,S)=>{if(S.in==="postgres")S.role=true}},
  {re:/^CREATE DATABASE mes_dev OWNER mes_app;$/i,out:(m,S)=>!S.role?{err:"ERROR:  role \"mes_app\" does not exist"}:"CREATE DATABASE",fx:(m,S)=>{if(S.role)S.db=true}},
  {re:/^\\q$/,out:"",fx:(m,S)=>{S.in=null}}],
 tasks:[{t:"Vào psql bằng tài khoản quản trị và xem phiên bản (nhớ dấu <code>;</code>).",check:(s,c)=>c.has("cmd",e=>/select version\(\);/i.test(e.line)&&e.ok)},
  {t:"Tạo người dùng <code>mes_app</code> và CSDL <code>mes_dev</code> thuộc mes_app; kiểm tra bằng <code>\\l</code>.",hint:"Tạo ROLE trước, DATABASE sau (cần chủ sở hữu tồn tại).",check:s=>s.S.db&&s.ran(/^\\l$/)},
  {t:"Thoát psql và chạy file lược đồ bằng tài khoản ứng dụng.",ok:"Ứng dụng dùng mes_app, không dùng postgres: lỡ lộ mật khẩu cũng chỉ ảnh hưởng CSDL dự án.",check:s=>s.S.schema}]}));

